import{_ as r}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as i,a as d,b as s}from"./chunks/theme-dark.DMCpB48j.js";import{_ as l,C as n,o as c,c as g,a2 as t,j as h,a,E as m}from"./chunks/framework.Dx-TCpNt.js";const x=JSON.parse('{"title":"简介","description":"KomaYomi —— Manga Learner —— 是一个本地优先的 Web 应用，用漫画学语言。你把同一份页面保留为日语、中文和英语三个版本，把页面切成一个个分格，并排阅读这些分格，再写下 Markdown 笔记；笔记始终挂在它所描述的那个分格上。","frontmatter":{"description":"KomaYomi —— Manga Learner —— 是一个本地优先的 Web 应用，用漫画学语言。你把同一份页面保留为日语、中文和英语三个版本，把页面切成一个个分格，并排阅读这些分格，再写下 Markdown 笔记；笔记始终挂在它所描述的那个分格上。"},"headers":[],"relativePath":"zh/guide/introduction.md","filePath":"zh/guide/introduction.md","lastUpdated":1794745555000}'),u={name:"zh/guide/introduction.md"};function p(f,o,_,b,v,P){const e=n("Badge");return c(),g("div",null,[o[2]||(o[2]=t('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>KomaYomi —— <strong>Manga Learner</strong> —— 是一个本地优先的 Web 应用，用漫画学语言。你把同一份页面保留为日语、中文和英语三个版本，把页面切成一个个分格，并排阅读这些分格，再写下 Markdown 笔记；笔记始终挂在它所描述的那个分格上。</p><p>它不是用来随意翻阅的漫画阅读器，也不是分发平台。一切都在你自己的机器上运行，读取你自己的图片文件夹。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>翻译最好按分格逐格研读，而不是按整页。但同一本书三种语言的扫描件很少能对齐：整页会偏移，分格的裁切范围不同，文字位置也各有出入。普通图片查看器只提供一个缩放级别，没有笔记，也无法表达“这个对话框，在这三个版本里”。</p><p>KomaYomi 补上了中间缺失的一层：</p><ol><li><strong>结构</strong> —— 分格会被检测出来，并以归一化矩形保存，因此无论缩放级别或导出尺寸如何变化都不会失效。</li><li><strong>对齐</strong> —— 每种语言都可以独立微调，让同一个分格真正重叠。</li><li><strong>笔记</strong> —— 每条记录都限定在某一页或某个分格，使用 Markdown，并支持标签和来源。</li></ol><h2 id="五步工作流" tabindex="-1">五步工作流 <a class="header-anchor" href="#五步工作流" aria-label="Permalink to &quot;五步工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>你要做什么</th><th>页面</th></tr></thead><tbody><tr><td>1</td><td>整理扫描图，按 <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</code> 摆好，或添加已有文件夹。</td><td><a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a>、<a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a></td></tr><tr><td>2</td><td>打开页面，让应用自动切格，再手动修正框。</td><td><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a></td></tr><tr><td>3</td><td>并排或叠加阅读 2–3 种语言，对齐画面，遮住正在自测的语言。</td><td><a href="/KomaYomi-docs/zh/guide/compare">对照阅读</a></td></tr><tr><td>4</td><td>写下整页笔记与格级笔记，带标签、来源和截图。</td><td><a href="/KomaYomi-docs/zh/guide/notes">笔记</a></td></tr><tr><td>5</td><td>导出学习用 HTML、用于幻灯片的 PNG，或带到另一台机器的工程包。</td><td><a href="/KomaYomi-docs/zh/guide/export">导出</a></td></tr></tbody></table><h2 id="界面一览" tabindex="-1">界面一览 <a class="header-anchor" href="#界面一览" aria-label="Permalink to &quot;界面一览&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="切格工作台：漫画页面、检测出的分格、缩放手柄与标注工具栏"><figcaption>切格工作台。顶栏：页面导航、分格 / 对照阅读、阅读顺序、主题、界面语言、笔记与导出。左侧：图库。右侧：笔记。中间：带分格框的页面。</figcaption></figure><p>窗口有五个始终不变的区域：</p><ul><li><strong>顶栏</strong> —— 品牌（返回图库）、卷 / 话 / 页、<code>‹</code> <code>›</code> 翻页箭头、保存指示器、<strong>分格 / 对照阅读</strong> 切换、阅读方向选择器、界面主题、界面语言、<strong>笔记</strong> 与 <strong>导出</strong>。</li><li><strong>图库侧栏</strong>（<code>S</code>）—— 卷 → 话 → 页，带逐页警告，以及添加漫画、目录规则、工程文件、交换文件和备份的入口。</li><li><strong>舞台</strong> —— 切格工作台或对照阅读，取决于视图切换。</li><li><strong>笔记栏</strong>（<code>N</code>）—— 整页笔记、格级笔记、总览搜索和随手记暂存。</li><li><strong>分隔条</strong> —— 拖动图库与舞台之间、或舞台与笔记之间的竖向手柄调整宽度；双击恢复默认。</li></ul><p>一页可以有一种、两种或三种语言。对照阅读中的语言标签只对当前页实际存在的语言启用。</p><h2 id="最初的十分钟" tabindex="-1">最初的十分钟 <a class="header-anchor" href="#最初的十分钟" aria-label="Permalink to &quot;最初的十分钟&quot;">​</a></h2><ol><li>启动应用（<code>npm run dev</code> 或桌面版），打开 <code>http://127.0.0.1:5173</code>。</li><li>在 <code>raw/</code> 下放一卷，或点击侧栏的 <strong>＋ 添加漫画</strong>，指向已有文件夹。</li><li>点击侧栏中的某一页。首次打开会自动检测分格，并把结果保存到 <code>data/pages/</code>。</li><li>切换到 <strong>对照阅读</strong>（<code>C</code>），勾选 <code>JA</code> 和 <code>ZH</code>，拖动某一栏直到分格对齐。</li><li>打开 <strong>笔记</strong>（<code>N</code>），选中一个分格，写下第一条笔记。按 <code>Ctrl+Enter</code> 保存。</li><li>按 <code>E</code> 导出 HTML 文件，在浏览器中打开。</li></ol><h2 id="已实现的功能" tabindex="-1">已实现的功能 <a class="header-anchor" href="#已实现的功能" aria-label="Permalink to &quot;已实现的功能&quot;">​</a></h2><div class="status-list"><div><strong>图库</strong> —— 扫描卷目录，识别语言目录别名，按排序位置配对页面，并对缺页和命名不一致给出警告。</div><div><strong>分格</strong> —— 自动 XY-cut 检测，新增 / 移动 / 八向缩放 / 合并 / 分组 / 删除，编号，百分比输入，网格生成器，分格模板，声明式布局，插件，跨会话页面历史。</div><div><strong>标注</strong> —— 箭头、矩形、椭圆、荧光笔、自由笔迹、文字、编号圆标和马赛克，页面级显示开关，支持 PNG 导出。</div><div><strong>对照</strong> —— 2–3 种语言，并排或叠加，按语言模糊 / 色块遮蔽，滚轮缩放，平移，整页 / 逐格 / 锚点 / 网格对齐，已保存的预设，自定义语言顺序。</div><div><strong>笔记</strong> —— 整页 / 格级笔记，带工具栏和实时预览的 Markdown，标签，来源，附图，总览搜索，复制给大模型，随手记暂存。</div><div><strong>导出</strong> —— HTML（图片目录或单文件）、PNG（整页、当前格、三语拼图）、分格边框叠加、打印样式、导出模板。</div><div><strong>存储</strong> —— 本地文件夹、挂载的网络共享和 WebDAV，按需拉取图片并使用有上限的 LRU 缓存。</div><div><strong>可移植性</strong> —— `.mnproj` 工程包，`.mntpl` / `.mnexp` / `.mnpage.json` 交换文件，备份与恢复 ZIP，带版本的 schema。</div></div><h2 id="尚未实现的功能" tabindex="-1">尚未实现的功能 <a class="header-anchor" href="#尚未实现的功能" aria-label="Permalink to &quot;尚未实现的功能&quot;">​</a></h2>',19)),h("p",null,[o[0]||(o[0]=a("以下内容在出现的位置都标记为 ",-1)),m(e,{type:"warning",text:"计划中"}),o[1]||(o[1]=a("：",-1))]),o[3]||(o[3]=t('<ul><li>PDF、Word（<code>.docx</code>）和词表导出。请使用 HTML 导出和浏览器的打印为 PDF。</li><li>离线写入队列与定时自动备份。</li><li>应用内的图片转换或批量重命名。请在导入前整理文件（见<a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a>）。</li><li>原生移动端应用。Web 界面在窄浏览器窗口中确实可用（见下文）。</li></ul><figure class="shot"><img src="'+i+'" alt="窄窗口中的对照阅读，各语言栏纵向堆叠"><figcaption>窄窗口：各栏纵向堆叠，图库收起为抽屉。这是响应式 Web 布局，不是原生应用。</figcaption></figure><h2 id="亮色与暗色" tabindex="-1">亮色与暗色 <a class="header-anchor" href="#亮色与暗色" aria-label="Permalink to &quot;亮色与暗色&quot;">​</a></h2><p>界面主题默认跟随系统，也可以在顶栏固定为亮色或暗色。导出的 HTML 只有亮色，以保证截图和打印结果一致。</p><figure class="shot"><img src="'+d+'" alt="亮色主题下的对照阅读"><figcaption>亮色主题。</figcaption></figure><figure class="shot"><img src="'+s+'" alt="暗色主题下的对照阅读"><figcaption>暗色主题。</figcaption></figure><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>图库里什么都没有。</strong> 侧边栏只扫描 <code>raw/</code>；先添加文件夹或挂载远端目录。参见<a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a>。</li><li><strong>第一页分格是错的。</strong> 自动检测只是草稿，不是结论。先修框再写格级笔记；之后重新检测会丢弃手动修改。</li><li><strong>某个语言标签是灰的。</strong> 这一页在该语言下没有图片。检查页数是否一致、卷的语言映射是否正确。</li><li><strong>换机器后笔记好像没了。</strong> 笔记在 <code>data/</code>，图片在 <code>raw/</code>；两者都要带走，或者导出 <code>.mnproj</code>。参见<a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a>。</li><li><strong>离线时图片请求失败。</strong> 只有离线前打开过的页面在缓存里。参见<a href="/KomaYomi-docs/zh/guide/remote">备份与远端</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>全新安装：<a href="/KomaYomi-docs/zh/guide/installation">安装与运行</a>。</li><li>图片还没整理好：<a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a>。</li><li>准备添加图片：<a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a>。</li><li>目录形状不常规：<a href="/KomaYomi-docs/zh/guide/folder-rules">目录识别规则</a>。</li><li>想找某个按键：<a href="/KomaYomi-docs/zh/guide/shortcuts">快捷键总表</a>。</li><li>遇到问题：<a href="/KomaYomi-docs/zh/faq">FAQ 与故障排查</a>。</li></ul>',10))])}const z=l(u,[["render",p]]);export{x as __pageData,z as default};
